class MyApp extends StatefulWidget {
  @override
  _MyAppState createState() => _MyAppState();
}

class _MyAppState extends State<MyApp> {
  int counter = 0;
  String lastAction = 'Кез келген батырманы басыңыз';

  void handlePress(String action) {
    setState(() {
      counter++;
      lastAction = action;
    });
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(title: Text('Flutter батырмалары')),
        body: Center(
          child: Padding(
            padding: EdgeInsets.all(16.0),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                // Басулар санауышы
                Text(
                  'Басулар: $counter',
                  style: TextStyle(
                    fontSize: 24,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                SizedBox(height: 10),
                Text(
                  lastAction,
                  style: TextStyle(fontSize: 16, color: Colors.grey),
                ),
                SizedBox(height: 30),

                // ElevatedButton - негізгі батырма
                ElevatedButton(
                  onPressed: () => handlePress('ElevatedButton басылды'),
                  child: Text('ElevatedButton'),
                ),
                SizedBox(height: 10),

                // ElevatedButton белгішемен
                ElevatedButton.icon(
                  onPressed: () => handlePress('Белгішелі батырма'),
                  icon: Icon(Icons.send),
                  label: Text('Жіберу'),
                ),
                SizedBox(height: 20),

                // TextButton - мәтіндік батырма
                TextButton(
                  onPressed: () => handlePress('TextButton басылды'),
                  child: Text('TextButton'),
                ),
                SizedBox(height: 20),

                // OutlinedButton - жиегі бар батырма
                OutlinedButton(
                  onPressed: () => handlePress('OutlinedButton басылды'),
                  child: Text('OutlinedButton'),
                ),
                SizedBox(height: 20),

                // IconButton қатары
                Text('IconButton:'),
                SizedBox(height: 10),
                Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    IconButton(
                      icon: Icon(Icons.favorite_border),
                      color: Colors.red,
                      iconSize: 30,
                      onPressed: () => handlePress('Жүрек'),
                    ),
                    IconButton(
                      icon: Icon(Icons.share),
                      color: Colors.blue,
                      iconSize: 30,
                      onPressed: () => handlePress('Бөлісу'),
                    ),
                    IconButton(
                      icon: Icon(Icons.bookmark_border),
                      color: Colors.green,
                      iconSize: 30,
                      onPressed: () => handlePress('Белгі'),
                    ),
                  ],
                ),
                SizedBox(height: 20),

                // Реттелген стильмен батырма
                ElevatedButton(
                  onPressed: () => handlePress('Әдемі батырма'),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.purple,
                    foregroundColor: Colors.white,
                    padding: EdgeInsets.symmetric(
                      horizontal: 40,
                      vertical: 15,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(30),
                    ),
                  ),
                  child: Text(
                    'Реттелген батырма',
                    style: TextStyle(fontSize: 16),
                  ),
                ),
                SizedBox(height: 20),

                // Белсенді емес батырма (onPressed = null)
                ElevatedButton(
                  onPressed: null, // белсенді емес
                  child: Text('Белсенді емес батырма'),
                ),
              ],
            ),
          ),
        ),
        // FloatingActionButton
        floatingActionButton: FloatingActionButton(
          onPressed: () => handlePress('FAB басылды'),
          child: Icon(Icons.add),
          tooltip: 'Қосу',
        ),
      ),
    );
  }
}

