class MyApp extends StatelessWidget {
  Widget buildBox(String text, Color color) {
    return Container(
      width: 80,
      height: 80,
      decoration: BoxDecoration(
        color: color,
        borderRadius: BorderRadius.circular(10),
        boxShadow: [
          BoxShadow(
            color: Colors.black26,
            blurRadius: 5,
            offset: Offset(2, 2),
          ),
        ],
      ),
      child: Center(
        child: Text(
          text,
          style: TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.bold,
          ),
          textAlign: TextAlign.center,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(title: Text('Center және Align')),
        body: SingleChildScrollView(
          child: Column(
            children: [
              // Center мысалы
              Container(
                height: 200,
                color: Colors.grey[200],
                child: Center(
                  child: buildBox('Center', Colors.blue),
                ),
              ),

              Padding(
                padding: EdgeInsets.all(16),
                child: Text(
                  'Align - әртүрлі позициялар:',
                  style: TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),

              // Align мысалдары - 9 позиция
              Container(
                height: 400,
                margin: EdgeInsets.all(16),
                decoration: BoxDecoration(
                  color: Colors.grey[200],
                  border: Border.all(color: Colors.blue, width: 2),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Stack(
                  children: [
                    // Жоғарғы сол
                    Align(
                      alignment: Alignment.topLeft,
                      child: buildBox('TL', Colors.red),
                    ),
                    // Жоғары орта
                    Align(
                      alignment: Alignment.topCenter,
                      child: buildBox('TC', Colors.orange),
                    ),
                    // Жоғарғы оң
                    Align(
                      alignment: Alignment.topRight,
                      child: buildBox('TR', Colors.yellow[700]!),
                    ),
                    // Сол орта
                    Align(
                      alignment: Alignment.centerLeft,
                      child: buildBox('CL', Colors.green),
                    ),
                    // Орталық
                    Align(
                      alignment: Alignment.center,
                      child: buildBox('C', Colors.blue),
                    ),
                    // Оң орта
                    Align(
                      alignment: Alignment.centerRight,
                      child: buildBox('CR', Colors.indigo),
                    ),
                    // Төменгі сол
                    Align(
                      alignment: Alignment.bottomLeft,
                      child: buildBox('BL', Colors.purple),
                    ),
                    // Төмен орта
                    Align(
                      alignment: Alignment.bottomCenter,
                      child: buildBox('BC', Colors.pink),
                    ),
                    // Төменгі оң
                    Align(
                      alignment: Alignment.bottomRight,
                      child: buildBox('BR', Colors.brown),
                    ),
                  ],
                ),
              ),

              Padding(
                padding: EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Реттелген туралау:',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    SizedBox(height: 10),
                    Container(
                      height: 200,
                      decoration: BoxDecoration(
                        color: Colors.grey[200],
                        borderRadius: BorderRadius.circular(10),
                      ),
                      child: Stack(
                        children: [
                          // Реттелген позиция 1
                          Align(
                            alignment: Alignment(-0.5, -0.5),
                            child: buildBox('A', Colors.teal),
                          ),
                          // Реттелген позиция 2
                          Align(
                            alignment: Alignment(0.7, 0.3),
                            child: buildBox('B', Colors.cyan),
                          ),
                        ],
                      ),
                    ),
                    SizedBox(height: 10),
                    Text(
                      'TL=TopLeft, TC=TopCenter, TR=TopRight\n'
                      'CL=CenterLeft, C=Center, CR=CenterRight\n'
                      'BL=BottomLeft, BC=BottomCenter, BR=BottomRight',
                      style: TextStyle(fontSize: 12, color: Colors.grey[600]),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

