              ),
            ),
            SizedBox(height: 40),

            // Material немесе Cupertino батырмасы
            if (useMaterial)
              ElevatedButton(
                onPressed: () {
                  setState(() {
                    useMaterial = !useMaterial;
                  });
                },
                child: Text('iOS стиліне ауысу'),
              )
            else
              CupertinoButton.filled(
                onPressed: () {
                  setState(() {
                    useMaterial = !useMaterial;
                  });
                },
                child: Text('Material стиліне ауысу'),
              ),

            SizedBox(height: 40),

            // Material немесе Cupertino белгішелер
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                if (useMaterial) ..[
                  Icon(Icons.favorite, size: 40, color: Colors.red),
                  SizedBox(width: 20),
                  Icon(Icons.star, size: 40, color: Colors.amber),
                  SizedBox(width: 20),
                  Icon(Icons.settings, size: 40, color: Colors.grey),
                ] else ..[
                  Icon(CupertinoIcons.heart_fill, size: 40, color: CupertinoColors.systemRed),
                  SizedBox(width: 20),
                  Icon(CupertinoIcons.star_fill, size: 40, color: CupertinoColors.systemYellow),
                  SizedBox(width: 20),
                  Icon(CupertinoIcons.settings, size: 40, color: CupertinoColors.systemGrey),
                ],
              ],
            ),

            SizedBox(height: 20),

            Text(
              useMaterial 
                ? 'Material: ашық түстер, көлеңкелер, анимациялар'
                : 'Cupertino: жұмсақ түстер, минимализм, iOS стилі',
              textAlign: TextAlign.center,
              style: TextStyle(color: Colors.grey[600]),
            ),
          ],
        ),
      ),
    );
  }
}

